// UI helpers use the main game's state; trialOriginal always retains the real save.
function habitsView(){
 if(state.age<18)return '';
 const h=LifeHabits.ensure(state),c=h.care;
 const names={tobacco:'Сигареты',alcohol:'Алкоголь',gambling:'Азартные игры',unknown:'Неизвестные вещества'};
 const urges=Object.entries(h.urges).filter(([,v])=>v>0);
 const plans={waiting:'Оценка состояния',combined:'Согласованный план лечения',therapy:'Психотерапия и наблюдение',maintenance:'Поддержка после лечения'};
 return `<section class="habits-panel"><h3>Состояние и привычки</h3><p>${esc(LifeHabits.context(state))}</p>${h.comfort?`<p class="acute-comfort">Краткое облегчение: +${h.comfort}<small>Временное ощущение, а не устойчивое счастье</small></p>`:''}${urges.length?urges.map(([key,value])=>`<div class="urge-row"><span>${names[key]} · тяга</span><strong>${value}/100</strong></div>`).join(''):'<p class="tiny">Заметной тяги пока нет.</p>'}${c.plan?`<p class="care-status">${plans[c.plan]||'Наблюдение'}${c.taper!==null?' · постепенное завершение':''}</p>`:''}<p class="tiny">Параметры этой системы пока игровые, не медицинская оценка.</p></section>`;
}
function habitChoiceView(p){return `<div class="chapter-line"><span>${['assessment','treatment','review'].includes(p.topic)?'ЗАБОТА О СЕБЕ':'МОМЕНТ ВЫБОРА'}</span><span>ВРЕМЯ НА ПАУЗЕ</span></div><h2 class="event-title">${esc(p.title)}</h2><p class="event-desc">${esc(p.text)}</p><div class="habit-context"><p>${esc(p.context)}</p>${p.appeal?`<small>Привлекательность сейчас: ${esc(p.appeal)} · тяга: ${esc(p.urge)}</small>`:''}</div><div class="choices">${p.options.map((o,i)=>decisionButton('habit',i,o.title,esc(o.desc))).join('')}</div><p class="tiny">Сюжет и числовые эффекты — тест игровой логики. Решение остаётся за вами.</p>`;}
function trialPicker(){openDialog(`<span class="eyebrow">ПРОВЕРКА СИТУАЦИЙ</span><h2>Сравнить разные состояния</h2><p>Отдельная тестовая сцена с взрослым персонажем. Основная жизнь сохранится. После проверки можно вернуться к ней.</p><label class="trial-label">Ситуация<select id="trial-kind"><option value="tobacco">Сигарета в компании</option><option value="alcohol">Алкоголь после тяжёлого дня</option><option value="lottery">Лотерейный билет</option><option value="gambling">Игра на деньги</option><option value="unknown">Неизвестная таблетка</option><option value="assessment">Обращение за помощью</option><option value="treatment">Согласованный план лечения</option><option value="career:jobs">Первая работа: сравнить предложения</option><option value="career:switch">Смена работы</option><option value="career:retrain">Переобучение без потери опыта</option><option value="career:promotion">Специалист или руководитель</option><option value="career:balance">Изменение рабочей нагрузки</option><option value="career:internship">Практика во время учёбы</option><option value="career:self">Собственное дело</option><option value="social:party">Встреча и разные интересы друзей</option><option value="social:connections">Предложение влиятельного знакомого</option><option value="social:bribe">Предложение взятки</option><option value="social:cover">Просьба прикрыть знакомого</option><option value="social:partner">Отношения с партнёром</option><option value="social:family">Родительство</option><option value="social:child">Трудности у ребёнка</option><option value="social:spouse">Партнёр хочет изменить жизнь</option><option value="social:reflection">Поиск опоры и смысла</option></select></label><label class="trial-label">Состояние<select id="trial-context"><option value="strained">Сильное истощение, мало поддержки</option><option value="steady">Есть силы, поддержка и приятные планы</option></select></label><p class="tiny">Для неизвестной таблетки используется тяжёлая ситуация; при благополучном состоянии предложение не появляется. Сюжет лечения моделируется отдельно от привычек.</p><button class="primary" id="start-trial">Открыть ситуацию →</button>`);$('#start-trial').onclick=()=>{const kind=$('#trial-kind').value,context=$('#trial-context').value;$('#dialog').close();startTrial(kind,context);};}
function startTrial(kind,context){
 if(!trialOriginal)trialOriginal=state;
 const s=E.fresh(trialOriginal.seed);s.started=true;s.born=true;s.age=24;s.step=4;s.childhood.finished=true;s.childhood.step=5;
 F.ensure(s);s.flow.months=288;s.flow.playing=false;s.flow.speed=3;s.flow.career.job='Специалист';s.flow.career.route='practice';s.flow.seen=F.sideStories.map(x=>x.month);
 const strained=context==='strained'||kind==='unknown'||kind==='assessment'||kind==='treatment';
 Object.assign(s.stats,strained?{joy:15,energy:18,bond:20,money:45}:{joy:82,energy:85,bond:82,money:60});
 const h=LifeHabits.ensure(s);h.lastMonth=288;h.nextOpportunity=10000;const testCareer=LifeCareer.ensure(s);testCareer.lastMonth=288;testCareer.seen=['school','internship'];testCareer.nextReview=10000;testCareer.searchAfter=10000;const testSocial=LifeSocial.ensure(s);testSocial.seen=['partner','family'];testSocial.nextParty=10000;testSocial.nextConnections=10000;testSocial.nextReflection=10000;
 if(kind==='assessment'||kind==='treatment'){h.care.symptomMonths=6;h.care.severity=65;}
 if(kind==='treatment')h.care.assessed=true;
 if(kind.startsWith('social:')){const topic=kind.slice(7);if(['child','spouse','reflection'].includes(topic)){s.age=40;s.step=7;s.flow.months=480;h.lastMonth=480;h.nextOpportunity=492;}const n=LifeSocial.ensure(s);n.lastMonth=s.flow.months;n.nextParty=10000;n.nextConnections=10000;n.nextReflection=10000;n.seen=['partner','family'];if(['connections','bribe','cover','child','spouse','reflection'].includes(topic)){n.access=75;n.ruleBreaking=3;n.controversy=40;n.trust=40;}if(topic==='spouse'){n.partner={name:'Алекс',values:'honest',closeness:45,changed:true};}if(topic==='child'){n.child={bornAt:372,trust:45,security:40,school:45,stress:55,latest:'В школе заметили ссоры и пропущенные задания. Нужно разобраться в причинах.'};n.nextChildEvent=312;}LifeSocial.offer(s,topic);}else if(kind.startsWith('career:'))startCareerTrial(s,kind.slice(7));else LifeHabits.offer(s,kind);F.add(s,'event','Отдельная тестовая ситуация. Её события не попадут в вашу основную жизнь.','home');
 state=s;tab='story';save();render();
}
function leaveTrial(){if(!trialOriginal)return;state=trialOriginal;trialOriginal=null;tab='story';$('#restart').disabled=false;save();render();}
function bindHabits(){
 document.querySelectorAll('[data-habit]').forEach(b=>b.onclick=()=>{if(F.resolve(state,Number(b.dataset.habit))){save();render();}});
 document.querySelectorAll('[data-open-trial]').forEach(b=>b.onclick=trialPicker);
 if($('#leave-trial'))$('#leave-trial').onclick=leaveTrial;
 $('#restart').disabled=Boolean(trialOriginal);
}

function socialChoiceView(p){return habitChoiceView({...p,context:'Отношения зависят от конкретных людей и поступков. Богатство, участие в вечеринке или отказ от неё не назначают человеку моральный ярлык.'});}
function socialPanel(){if(state.age<14)return '';const n=LifeSocial.ensure(state),c=n.child,childAge=c?Math.max(0,Math.floor((F.ensure(state).months-c.bornAt)/12)):0;return `<section class="habits-panel"><h3>Отношения и репутация</h3>${n.friends.map(p=>`<div class="urge-row"><span>${esc(p.name)}<small class="person-focus">${esc(p.focus)}</small></span><strong>${p.closeness}/100</strong></div>`).join('')}<div class="urge-row"><span>Репутация · доверие</span><strong>${n.trust}/100</strong></div><div class="urge-row"><span>Сомнительная известность</span><strong>${n.controversy}/100</strong></div>${n.partner?`<p>Алекс · близость ${n.partner.closeness}/100<br><small>${n.partner.values==='complicit'?'Разделяет привычные договорённости вашего круга':n.partner.values==='honest'?'Ценит открытость и границы':'Сохраняет собственные взгляды'}</small></p>`:''}${c?`<p>Ребёнок · ${childAge} лет<br><small>Доверие ${c.trust}/100 · чувство безопасности ${c.security}/100${childAge>=6&&childAge<18?' · учёба '+c.school+'/100':''}</small></p>`:''}<p class="tiny">Это игровые оценки связей и последствий, не рейтинг ценности человека.</p></section>`;}
